grammar = {'S': [('NP','VP')], 'NP': [('Det','N')], 'VP': [('V','NP')]}
lex = {'the':'Det', 'boy':'N', 'cake':'N', 'ate':'V'}
words = 'the boy ate the cake'.split()
n = len(words)
table = {}
for i, w in enumerate(words, 1):
    table[(i, i)] = {lex[w]}
splits = 0
for L in range(2, n + 1):
    for i in range(1, n - L + 2):
        j = i + L - 1
        cell = set()
        for k in range(i, j):
            splits += 1
            for A, rules in grammar.items():
                for (B, C) in rules:
                    if B in table[(i, k)] and C in table[(k + 1, j)]:
                        cell.add(A)
        table[(i, j)] = cell
print(splits)
